import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 마감 상태로 보는 급여 지급일 상태
const CLOSED_STATUSES = ['마감', '전표처리'];
const CLOSED_REASON = '마감된 급여 데이터는 마감취소 없이 덮어쓸 수 없습니다.';

interface ErrorItem {
  index: number;
  employeeId: unknown;
  month: unknown;
  payItemId: unknown;
  reason: string;
}

function isId(v: unknown): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v > 0;
}

function amountOf(v: unknown): string | null {
  if (typeof v === 'number') {
    return Number.isFinite(v) && v >= 0 ? String(v) : null;
  }
  if (typeof v === 'string' && /^\d+(\.\d{1,2})?$/.test(v.trim())) {
    return v.trim();
  }
  return null;
}

@Controller('api/v1')
export class FnSfr02103Controller {
  @Post('/payroll-item-amounts/bulk-enter')
  @HttpCode(200)
  async bulkEnterPayrollItemAmounts(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const year = data['attributionYear'];
    if (typeof year !== 'number' || !Number.isInteger(year) || year < 1900 || year > 2999) {
      throw new ApiError(400, 'VALIDATION_FAILED', '귀속 연도를 올바르게 입력해 주세요.');
    }
    const items = data['items'];
    if (!Array.isArray(items)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '급여 항목 금액 목록을 입력해 주세요.');
    }
    if (items.length === 0) {
      throw new ApiError(422, 'PAYROLL_INPUT_INVALID', '입력된 급여 항목이 없습니다.');
    }
    return transaction(async (db) => {
      const errors: ErrorItem[] = [];
      const accepted = new Set<number>();
      let acceptedCount = 0;
      const employeeOk = new Map<number, boolean>();
      const payItemOk = new Map<number, boolean>();
      const paydays = new Map<number, { paydayId: number; status: string } | null>();

      for (let i = 0; i < items.length; i++) {
        const row = items[i] as Record<string, unknown> | null;
        const raw = row && typeof row === 'object' ? row : {};
        const employeeId = raw['employeeId'];
        const month = raw['month'];
        const payItemId = raw['payItemId'];
        const fail = (reason: string) => {
          errors.push({ index: i, employeeId, month, payItemId, reason });
        };
        if (!isId(employeeId)) {
          fail('임직원 ID 형식이 올바르지 않습니다.');
          continue;
        }
        if (typeof month !== 'number' || !Number.isInteger(month) || month < 1 || month > 12) {
          fail('월은 1~12 사이 정수여야 합니다.');
          continue;
        }
        if (!isId(payItemId)) {
          fail('지급공제항목 ID 형식이 올바르지 않습니다.');
          continue;
        }
        const amount = amountOf(raw['amount']);
        if (amount === null) {
          fail('금액은 0 이상의 숫자여야 합니다.');
          continue;
        }

        if (!employeeOk.has(employeeId)) {
          const found = await db.query(
            'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
            { employeeId },
          );
          employeeOk.set(employeeId, found.length > 0);
        }
        if (!employeeOk.get(employeeId)) {
          fail('존재하지 않는 임직원입니다.');
          continue;
        }
        if (!payItemOk.has(payItemId)) {
          const found = await db.query(
            'SELECT pay_item_id AS "payItemId" FROM pay_item WHERE pay_item_id = CAST(:payItemId AS bigint)',
            { payItemId },
          );
          payItemOk.set(payItemId, found.length > 0);
        }
        if (!payItemOk.get(payItemId)) {
          fail('존재하지 않는 지급공제항목입니다.');
          continue;
        }

        if (!paydays.has(month)) {
          const attributionMonth = String(year) + String(month).padStart(2, '0');
          // 가정: 귀속 연월이 같은 지급일이 여럿이면 지급일이 가장 빠른 것을 쓴다
          const found = await db.query(
            'SELECT payday_id AS "paydayId", status AS "status" FROM payday WHERE attribution_month = :attributionMonth ORDER BY pay_date, payday_id LIMIT 1',
            { attributionMonth },
          );
          paydays.set(
            month,
            found.length > 0 ? { paydayId: Number(found[0].paydayId), status: String(found[0].status) } : null,
          );
        }
        const payday = paydays.get(month);
        if (!payday) {
          fail('해당 귀속 연월의 급여 지급일이 등록되어 있지 않습니다.');
          continue;
        }
        if (CLOSED_STATUSES.includes(payday.status)) {
          fail(CLOSED_REASON);
          continue;
        }

        let payrolls = await db.query(
          'SELECT payroll_id AS "payrollId" FROM payroll WHERE payday_id = CAST(:paydayId AS bigint) AND employee_id = CAST(:employeeId AS bigint)',
          { paydayId: payday.paydayId, employeeId },
        );
        if (payrolls.length === 0) {
          payrolls = await db.query(
            'INSERT INTO payroll (payday_id, employee_id, created_at, updated_at) VALUES (CAST(:paydayId AS bigint), CAST(:employeeId AS bigint), now(), now()) RETURNING payroll_id AS "payrollId"',
            { paydayId: payday.paydayId, employeeId },
          );
        }
        await db.execute(
          'INSERT INTO payroll_item_amount (payroll_id, pay_item_id, amount, created_at, updated_at) VALUES (CAST(:payrollId AS bigint), CAST(:payItemId AS bigint), CAST(:amount AS numeric), now(), now()) ON CONFLICT (payroll_id, pay_item_id) DO UPDATE SET amount = CAST(:amount AS numeric), updated_at = now()',
          { payrollId: payrolls[0].payrollId, payItemId, amount },
        );
        acceptedCount += 1;
        accepted.add(employeeId);
      }

      if (acceptedCount === 0) {
        const allClosed = errors.length > 0 && errors.every((e) => e.reason === CLOSED_REASON);
        if (allClosed) {
          throw new ApiError(409, 'PAYROLL_CLOSED', CLOSED_REASON);
        }
        throw new ApiError(422, 'PAYROLL_INPUT_INVALID', '입력 형식 또는 필수값 오류로 반영된 건이 없습니다.');
      }

      // 가정: 연간 집계는 귀속 연도의 모든 항목 금액 합계(지급·공제 구분 없이)
      const annualSummaries: { employeeId: number; attributionYear: number; annualAmount: number }[] = [];
      for (const employeeId of accepted) {
        const sums = await db.query(
          'SELECT COALESCE(SUM(a.amount), 0) AS "annualAmount" FROM payroll_item_amount a JOIN payroll p ON p.payroll_id = a.payroll_id JOIN payday d ON d.payday_id = p.payday_id WHERE p.employee_id = CAST(:employeeId AS bigint) AND d.attribution_month LIKE :prefix',
          { employeeId, prefix: String(year) + '%' },
        );
        annualSummaries.push({
          employeeId,
          attributionYear: year,
          annualAmount: Number(sums[0].annualAmount),
        });
      }

      return {
        acceptedCount,
        rejectedCount: errors.length,
        errors,
        annualSummaries,
      };
    });
  }
}

