import { useState } from 'react';
import {
  call,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Band,
  RefName,
  Select,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface EntryRow {
  employeeId: number | string;
  month: string;
  payItemId: number | string;
  amount: number | string;
}

interface BulkResult {
  acceptedCount: number;
  rejectedCount: number;
  errors: Row[];
  annualSummaries: Row[];
}

const MONTHS: [string, string][] = Array.from({ length: 12 }, (_, i) => [String(i + 1), `${i + 1}월`]);

function emptyRow(): EntryRow {
  return { employeeId: '', month: '', payItemId: '', amount: '' };
}

export default function FnSfr02103Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [year, setYear] = useState<number | string>(new Date().getFullYear());
  const [rows, setRows] = useState<EntryRow[]>([emptyRow()]);
  const [result, setResult] = useState<BulkResult | undefined>(undefined);
  const [resultYear, setResultYear] = useState<number | string>('');

  const update = (index: number, patch: Partial<EntryRow>) => {
    setRows(rows.map((r, i) => (i === index ? { ...r, ...patch } : r)));
  };

  const submit = async () => {
    if (year === '' || typeof year !== 'number') {
      throw new Error('귀속 연도를 입력해 주세요.');
    }
    for (let i = 0; i < rows.length; i++) {
      const r = rows[i];
      if (r.employeeId === '' || r.month === '' || r.payItemId === '' || r.amount === '') {
        throw new Error(`${i + 1}번째 줄의 임직원, 월, 지급공제항목, 금액을 모두 입력해 주세요.`);
      }
    }
    const items = rows.map((r) => ({
      employeeId: r.employeeId,
      month: Number(r.month),
      payItemId: r.payItemId,
      amount: r.amount,
    }));
    const res = await call<BulkResult>('POST', '/payroll-item-amounts/bulk-enter', role, {
      attributionYear: year,
      items,
    });
    setResult(res);
    setResultYear(year);
    setOpen(false);
    setRows([emptyRow()]);
    notify('연간 급여를 입력했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>입력 결과</h2>
        <Band>
          <button type="button" onClick={() => setOpen(true)}>
            연간 급여 일괄 입력
          </button>
        </Band>
        {result ? (
          <Tiles
            items={[
              ['귀속 연도', resultYear],
              ['반영된 건수', <Num value={result.acceptedCount} />],
              ['오류로 제외된 건수', <Num value={result.rejectedCount} />],
            ]}
          />
        ) : (
          <p>아직 입력한 내역이 없습니다. 버튼을 눌러 연간 급여를 입력하세요.</p>
        )}
      </section>
      <section className="box span-6">
        <h2>임직원별 연간 급여</h2>
        <DataTable
          rows={result ? result.annualSummaries : []}
          empty="집계 결과가 없습니다."
          columns={[
            {
              key: 'employeeId',
              label: '임직원',
              render: (r) => <RefName table="employee" role={role} value={r.employeeId} />,
            },
            { key: 'attributionYear', label: '귀속 연도' },
            { key: 'annualAmount', label: '연간 급여 합계', render: (r) => <Num value={r.annualAmount} /> },
          ]}
        />
      </section>
      <section className="box span-6">
        <h2>오류 항목</h2>
        <DataTable
          rows={result ? result.errors : []}
          empty="오류 항목이 없습니다."
          columns={[
            { key: 'index', label: '순번', render: (r) => <Num value={Number(r.index) + 1} /> },
            {
              key: 'employeeId',
              label: '임직원',
              render: (r) =>
                typeof r.employeeId === 'number' ? (
                  <RefName table="employee" role={role} value={r.employeeId} />
                ) : (
                  '-'
                ),
            },
            { key: 'month', label: '월' },
            { key: 'reason', label: '사유' },
          ]}
        />
      </section>
      {open && (
        <Drawer title="연간 급여 일괄 입력" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="입력" note="오류가 있는 줄은 제외하고 정상 건만 반영됩니다. 마감된 급여는 덮어쓸 수 없습니다.">
            <Field label="연말정산 귀속 연도" required>
              <NumberInput value={year} onChange={setYear} />
            </Field>
            {rows.map((r, i) => (
              <div key={i}>
                <Field label={`${i + 1}번째 임직원`} required>
                  <LookupSelect
                    table="employee"
                    role={role}
                    value={r.employeeId}
                    onChange={(v) => update(i, { employeeId: v })}
                  />
                </Field>
                <Field label="월" required>
                  <Select value={r.month} onChange={(v) => update(i, { month: v })} options={MONTHS} />
                </Field>
                <Field label="지급공제항목" required>
                  <LookupSelect
                    table="pay_item"
                    role={role}
                    value={r.payItemId}
                    onChange={(v) => update(i, { payItemId: v })}
                  />
                </Field>
                <Field label="금액" required>
                  <NumberInput value={r.amount} onChange={(v) => update(i, { amount: v })} />
                </Field>
                {rows.length > 1 && (
                  <button type="button" onClick={() => setRows(rows.filter((_, k) => k !== i))}>
                    이 줄 삭제
                  </button>
                )}
              </div>
            ))}
            <button type="button" onClick={() => setRows([...rows, emptyRow()])}>
              줄 추가
            </button>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
